"""How-to guide topics for the Bulletin Designer. Each topic: id, title, keywords, steps (list of strings)."""

TOPICS = [
    ("start", "Start here: the weekly routine", "start begin weekly routine workflow new bulletin week steps overview how",
     ["Click Bulletins, type the Sunday date and press Create bulletin. Sections that are 'kept' arrive filled in from last week; weekly ones start blank. Or press Duplicate on an existing bulletin or template to start from a full copy (see 'Copy a bulletin').",
      "Open each section from the overview and type or paste the text. Press Save section.",
      "Use Preview to see the pages exactly as they will print. Press 'Check my bulletin' to find problems, and fix anything flagged in red (see 'Text is cut off').",
      "Made a mistake? 'Undo / history' on the overview restores an earlier version (see 'Go back to an earlier version').",
      "When it looks right, press Publish, then download the Print PDF for the printer and the Web PDF for posting online."]),
    ("giving", "Stewardship & Giving: collections", "giving stewardship generosity collection first second direct deposit dollar amount offertory hide",
     ["Open Stewardship & Giving. Choose the date, then type the dollar amount for the 1st Collection and the Direct Deposit.",
      "Type the 2nd Collection amount. If there is no second collection this week, tick 'There is no 2nd collection this week' (or leave the amount empty) and it is left out of the bulletin.",
      "Anything else goes in Notes. Leave an amount empty to leave it out. Press Save section."]),
    ("jump", "Find your way around the overview", "jump menu overview navigate find section list top buttons check history suggestions graphics assistant",
     ["The top buttons are Preview / print, Check my bulletin, Undo / history, Help, Web PDF, Print PDF and 'Liturgical suggestions & graphics'.",
      "Use the Jump to section menu to go straight to any section instead of scrolling.",
      "Each section row has Up, Down and Remove buttons and its page settings (see 'Move sections, columns and pages'). Remove only takes it out of this bulletin (any section, admin or editor, before it is published). Removed sections are listed at the bottom with an 'Add back' button. The grid also has space before title, space between paragraphs, Hide the title and 'Leave out of Table of Contents' (the section still prints, it just is not listed).",
      "'Add a section to this week's bulletin' adds a one-time section. Admins add permanent sections on the Sections page.",
      "'Ask the assistant' answers questions about the bulletin. 'Liturgical suggestions & graphics' proposes readings, feast days and pictures for the week."]),
    ("history", "Go back to an earlier version", "undo history restore earlier version mistake back revert deleted lost snapshot",
     ["Admins and editors: on the overview press 'Undo / history'. It lists saved versions of the bulletin (each save, move, photo or reset is recorded; the last 40 are kept).",
      "Press 'Go back to this' next to the version you want. Your text, photos and layout go back to that moment.",
      "Restoring is itself recorded, so you can change your mind and go forward again."]),
    ("check", "Check my bulletin", "check problems warnings missing alt text empty sections pages errors review",
     ["Press 'Check my bulletin' on the overview. It lists things to fix: missing picture descriptions, empty sections, text that does not fit.",
      "Fix the items, then check again before you Publish."]),
    ("section", "Edit a section's text", "edit text type paste section words write content body",
     ["On the overview, click a section name (or use the Jump to section menu).",
      "Type in the big box. Press Enter to start a new paragraph. Press Shift+Enter (or the Soft return button) to start a new line with no extra gap.",
      "You can upload a Word (.docx) or .txt file instead of typing.",
      "Press Save section. Nothing is final until you save."]),
    ("style", "Make words bold, italic, underlined, colored or a different size", "bold italic underline color colour size font style highlight remove styling superscript",
     ["In the section's text box, select (highlight) the words.",
      "Click Bold, Italic, Underline, Apply color or Apply size. Click Remove styling to undo it on the selected words.",
      "You can highlight several paragraphs at once and apply a size or color; every paragraph gets it.",
      "The box shows small markers like ** ** or __ __ around the words. Leave them in place; they print as styling.",
      "Things like 2nd and 3rd become small raised letters automatically. Use styling sparingly: one or two highlights per page reads best."]),
    ("photo", "Add a photo to a section", "photo picture image upload add crop zoom position inset only graphic",
     ["Open the section. Choose a photo from the Photo library, or upload a new one (JPG or PNG).",
      "Use the Crop and zoom sliders; the picture is never stretched.",
      "'Where the photo goes' lets you put it below the text, above the title, beside the text, or Photo only (no text).",
      "To make the photo bigger or smaller, type a number in 'Photo width'. It is a percent of the page width: 0 keeps the standard size, 60 or 70 makes it bigger, 100 is the full width. If the photo is set to 'Inset at left/right, text wrapped', keep it at 60 or less so the words have room beside it (the app stops at 60). The height follows automatically, so the picture is never stretched.",
      "Add a short description of the picture for people who cannot see it (alt text), or tick Decorative."]),
    ("library", "Photo library: automatic keywords and search", "photo library metadata keywords tags exif camera date search find title description auto",
     ["When you add a photo to the library, the app reads the information stored inside the picture: its keywords, title, description, who took it, copyright, the date taken, the camera and the size. Keywords become tags, and the description is used as the alt text.",
      "Title is optional. If you leave it blank the app uses the picture's own title, or tidies up the file name.",
      "Type your own title, description or extra tags to add to or replace what was found. If a picture has no description of its own, you still need to describe it (or tick Decorative).",
      "Admins and editors can add many at once: in 'Bulk add photos' choose several photos, or one .zip file of photos, and press Add all. Each photo is shrunk to a good size for print and web (longest side 2400 pixels, never stretched) and gets a small preview picture so the library opens quickly.",
      "Bulk photos with no description of their own are still added, using their title as the description and tagged needs-description. Search that tag to find and fix them.",
      "Libraries group photos, for example Church, Logos and Religious. Click a library name to see only those photos. Admins and editors create, rename and remove libraries, and tick the libraries on each photo card and press 'Save libraries'. One photo can be in several libraries. Removing a library never deletes photos. When choosing a photo for a section, its libraries are shown after its name.",
      "Search finds a photo by title, tag, description or camera. For better searching later, add keywords to your photos before uploading (most phone and photo apps let you). The location (GPS) is never kept.",
      "Want to just look? 'Browse photos' in the top menu shows small pictures only, with search and library buttons, and none of the upload forms."]),
    ("photorow", "Put several photos in a section", "several multiple photos row side by side equal same size height width align top bottom gap caption square tall wide",
     ["Open the section and look for 'More photos in this section'. Add each photo and choose whether it goes above or below the text.",
      "Type a description for each photo; it prints under the photo as a caption.",
      "'Make the photos in a row': 'Equal presence' makes a square, a wide and a tall photo look the same size. 'All the same height' or 'All the same width' are the other choices.",
      "Use 'Height of the photos' to make the whole row bigger or smaller, 'Space between photos' for the gap, and 'Place the group' for centered, left or right.",
      "If the photos have different heights, 'line them up at the' Top, Middle or Bottom decides how they sit next to each other."]),
    ("tocspace", "Remove the space above 'In this issue'", "contents toc in this issue space above gap header picture",
     ["On the overview, in the contents settings, type 0 in 'Space above heading' and press Save contents settings. The heading then sits right under the header picture. Type a number like 0.1 for a little space."]),
    ("sharepage", "Put two sections with photos on one page", "two sections same page photos share stack one above other full width",
     ["Set both sections to Full page (or the 'under/over' width) and give both the same 'On page' number. The second one sits under the first.",
      "For a page that is only one photo, choose Where the photo goes: Photo only. It then fills the page as large as it can without stretching.",
      "The app makes the photos on that page smaller automatically so the text and photos fit together. If it is still too full, shorten the text."]),
    ("duplicate", "Copy a bulletin / use one as a template", "duplicate copy template instructions help reuse design clone",
     ["On the Bulletins list, pick a date next to a bulletin and press Duplicate. You get a full copy: every section, photo and layout.",
      "Press 'Mark as template' on a bulletin you like (for example one with instructions or help notes). It is labeled Template in the list. Duplicate it any time to start a new bulletin from that design."]),
    ("accounts", "Invite someone, or recover a forgotten password", "email invite register account password forgot reset editor user",
     ["Admin: open Users, fill in 'Invite a user' with their email and pick Editor, then Send invitation. They get an email with a link to choose their own password. Their email is their sign-in.",
      "Forgot a password? On the sign-in page press 'Forgot your password?', type your email, and use the link in the email (good for 2 hours).",
      "The Users page lists everyone with their access level, whether they are verified (finished registering), whether they are online now, and their last sign-in. Editors can add and manage users at the Editor level or below; only the admin manages admins and backups.",
      "To stop someone signing in, press Deactivate next to their name (Reactivate turns them back on). Delete removes the account for good. You cannot remove yourself or the last administrator.",
      "If the server cannot send email yet, the screen shows the link so you can send it yourself. Ask the admin to resend any time with 'Email registration link'."]),
    ("totalpages", "Set how many pages the bulletin has", "total pages number count 12 16 extra blank four multiple",
     ["On the overview, type the number in 'Total pages in this bulletin' (for example 12) and press Set.",
      "Leave it at 0 and the app fills out to a multiple of 4 pages (needed for a folded booklet).",
      "The app adds blank pages only up to your number. If your sections need more pages than that, it shows the pages needed; shorten text or change sizes to reach your number."]),
    ("youthcal", "Youth Group Calendar", "youth group calendar events location cards colorful fun",
     ["Each event shows as a colorful card with a big date badge, the event name, the day, time and location. Colors rotate automatically.",
      "Fill in Date, Time, Event and Location for each event, then Save section. Use '+ Add another event' for more.",
      "For an event that lasts several days, also choose 'Last day'. The card then shows a range such as NOV 6-8 and 'Friday to Sunday'. Leave it empty for a one-day event.",
      "Click in the Event box to pick a regular event (Special Event, Edge Night, Rock the Universe, Ash Wednesday, End of Year Party) or type your own. At the bottom of the page, 'Add a regular or yearly event' adds a new name to the list for good.",
      "When you start the next bulletin, events that already happened are dropped and upcoming ones carry over."]),
    ("hidetitle", "Hide a section's title", "hide title heading remove title",
     ["Open the section and tick 'Hide this section's title in the bulletin', then Save section."]),
    ("spacing", "Spacing between lines, paragraphs and sections", "spacing space gap between paragraphs lines tight loose default",
     ["Each section has three spacing boxes: under the title, between items, and between paragraphs, measured in inches.",
      "Leave a box blank for the standard spacing. Type 0 for none. Typical values are 0.05 to 0.2.",
      "If spacing looks wrong after experimenting, click 'Reset layout to standard' on the section. Your text and photos are kept."]),
    ("reset", "Undo my layout changes (reset)", "reset undo restore standard default fix messed broken layout moved",
     ["Open the section and click 'Reset layout to standard'. It puts spacing, columns, page, size and photo position back to normal and keeps your text and photos.",
      "To reset every section at once, use 'Reset layout of all sections' on the bulletin overview."]),
    ("notes", "Tell the admin what to improve", "note notes admin feedback problem improve suggestion idea bug broken",
     ["Click 'Notes to admin' at the top of any page. It remembers which page you were on.",
      "Write what was hard or what you wish it did, in your own words, and click Send note. You can see your own notes and whether they are Open or Done.",
      "The admin reads all notes and works through them with the AI helper. You do not need to describe it technically."]),
("photo-fit", "Photo size and empty space on a page", "photo size bigger larger smaller space gap empty bottom page fit columns balanced automatic",
     ["You do not need to size photos by hand. When a section with a photo shares a page with another section, the photo grows to fill the empty room left on the page and never pushes the next section off.",
      "Columns also fix themselves: choose 2 or 3 columns for a section and the lines are split evenly across them.",
      "Preview and the PDF both measure the real page, so a page you changed (more or less text) re-fits on its own. Reload Preview if a page looks off.",
      "If a photo still looks too small, the photo is probably as wide as the page allows. Try photo position 'below' or fewer lines of text above it. A red 'cut off at the bottom' warning means the page has too much; shorten the text or move a section to another page.",
      "Giving a section its own page, or turning on Hide the title, also frees more room for the photo."]),
("order", "Move sections, columns and pages", "move order position column columns pages width half left right page number reorder",
     ["On the overview, each section row has Pages, Columns, Width, Order and On page. Up and Down move a section one place; the settings grid is condensed to fit more on the screen.",
      "Order sets position (1 = first). Width Left half / Right half puts two sections side by side; the Left, Middle and Right third options give three across. Columns 1, 2 or 3 splits one section's text into columns. To put a full-width section over or under side-by-side sections, choose Width \"Full width, over the sections below it\" or \"Full width, under the sections above it\" and give it an Order number next to those sections.",
      "'On page' puts a section on a chosen page number. Two full-page sections with the same 'On page' share that page, one under the other (see 'Put two sections with photos on one page'). Half and third-width sections can also share a page.",
      "Dragging section corners to resize is switched off for editors for now, because it sometimes moved sections the wrong way. Use Columns, Width, Order and On page above instead. Ideas to make dragging dependable: show a preview of where things will land before it applies; add an Undo button right on the page; snap only to whole-page choices; and never move a section you did not drag.",
      "Pages makes a section take more than one page. Its text prints on the first page; the others are left for photos or notes.",
      "Change one thing at a time and check the Preview. If it gets confusing, use Reset layout."]),
    ("cutoff", "Text is cut off (red warning)", "cut off overflow red warning too long does not fit page full trim shorten",
     ["A red bar at the bottom of a page names sections that do not fit, and they get a red dashed outline.",
      "Fix it by shortening the text, reducing spacing, lowering the font size, moving the section to another page, or giving it a second page.",
      "Never shrink text below 12 pt; older readers need it large."]),
    ("ads", "Business card advertisements", "ads advertisement business card sponsor advertiser pdf upload last pages",
     ["Click Advertisements. Upload the cards (JPG, PNG or PDF), several at once if you like.",
      "They are sized and arranged automatically on the last two pages with the sponsor and 'Advertise With Us' banners.",
      "To use a different number of pages, open the bulletin's Overview and set 'Pages for advertisements' (0 = automatic, up to 2). The cards are spread evenly over that many pages.",
      "Use the Active tick-box to leave a card out, and the position number to reorder. Cards usually stay the same week to week."]),
    ("footer", "Header, footer and page numbers", "footer header page number date title theme office hours",
     ["On the overview, set the header date and title (for example Thirtieth Sunday in Ordinary Time) and the footer text.",
      "'Header photo' sets the picture across the top of page 1: zoom and position it, and choose a style. 'In this issue' (contents) has its own settings: title, which page it starts on, columns, size and spacing (see 'Remove the space above In this issue').",
      "'No stragglers' avoids a single leftover line at the top of a page, and 'Underlines' turns link underlines on or off.",
      "Page 1 has the full footer; later pages have a slim one-line footer with the page number to save room."]),
    ("copy", "Carry content to next week", "copy next week carry forward keep weekly blank repeat",
     ["A new bulletin copies standing sections (and their layout, header, footer and contents settings) from the previous one. Weekly sections start blank, except Youth Group events that have not happened yet.",
      "'Copy to next bulletin' sends a section to next Sunday's bulletin.",
      "Admins and editors can choose 'Keep for all editions' (stays filled in) or weekly (starts blank) for each section."]),
    ("review", "Review, approve and publish", "review approve publish pending status proofread published lock",
     ["Contributors submit sections; an editor approves them. Pending sections do not print until approved.",
      "Press Publish when the bulletin is final. Published bulletins are locked. Admins and editors can press 'Unpublish (reopen for edits)' if something must change, then Publish again.",
      "Viewers can only read. Access levels: Admin (everything), Editor (all sections, approve, publish, manage users at their level or below), Contributor (only assigned sections), Viewer (read only)."]),
    ("design", "Simple design rules (no designer needed)", "design tips good looking professional fonts colors font size readable consistent white space",
     ["Keep it consistent: the app already sets fonts and colors. Resist adding many colors or sizes.",
      "Use white space. A page that feels a little empty reads better than a crowded one.",
      "Use bold for the one thing a reader must not miss; avoid ALL CAPS and long underlined text.",
      "Use photos that are sharp and well lit, at least 1000 pixels wide. Crop out empty background.",
      "Short paragraphs and one idea each. Put dates and times first.",
      "Always read the Preview start to finish before printing, and have a second person proofread names and times."]),
    ("login", "Sign-in and password problems", "login password forgot sign in reset account locked user",
     ["Sign in with your email address and password. Use Sign out at the top right; the Password link changes your password.",
      "Forgot it? On the sign-in page press 'Forgot your password?' and use the emailed link (see 'Invite someone, or recover a forgotten password').",
      "'This account is deactivated' means an administrator turned it off. Ask them to Reactivate you on the Users page.",
      "If the email never arrives, check spam, or ask an admin to send the registration link again from the Users page."]),
    ("sections", "Add or remove sections (admin)", "sections admin add new section remove custom permanent weekly keep",
     ["Admins: the Sections page renames, orders and sets the default page count of the permanent sections, and marks each as 'kept' (carried forward) or weekly (starts blank).",
      "Editors can add a one-time section to a single bulletin with 'Add a section to this week's bulletin' on the overview."]),
]
